#include <iostream>
#include <vector>
using namespace std;

int main(){
  int n;
  cin >> n;
  vector<long long> sum(n + 1), size(n + 1);
  long long ans = 0;
  for (int k = 1; k <= n; ++k) {
    int x;
    cin >> x;
    ans += (k - 1) * size[x] - sum[x] - (size[x] * (size[x] - 1) / 2);
    size[x] += 1;
    sum[x] += k;
  }
  cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    int N;
    cin>>N;
    vector<int> a(N);
    vector<vector<ll>> pos(N);
    for(int i = 0; i < N; ++i){
        cin>>a[i];
        --a[i];
        pos[a[i]].push_back(i);
    }
    ll res = 0;
    for(auto p : pos){
        ll n = size(p);
        for(int m = 0; m < n - 1; ++m){
            res += (p[m + 1] - p[m] - 1) * (m + 1) * (n - (m + 1));
        }
    }
    cout<<res<<endl;
}
